head.script:
// Remove Homepage "lottie" animation for mobile or small screens for performance
document.addEventListener('readystatechange', () => {
  // DOM ready
  if (document.readyState === 'interactive') {
    if (window.innerWidth <= 992) {
      document.querySelector('.lottie-wrap')?.remove();
    }
  }
});

body.script:
/* Navbar scroll behaviour: hide on scroll down, show on scroll up, background on scroll, is-at-top class */
document.addEventListener('DOMContentLoaded', () => {
  const navbar = document.querySelector('.navbar_component');
  if (!navbar) return;

  const computed = getComputedStyle(navbar);
  const hiddenY = (() => {
    const h = navbar.offsetHeight;
    return Number.isFinite(h) && h > 0 ? `-${h}px` : '-4.75rem';
  })();

  if (!computed.transition || computed.transition === 'all 0s ease 0s') {
    navbar.style.transition = 'transform 200ms ease, background-color 200ms cubic-bezier(.25, .46, .45, .94)';
    navbar.style.willChange = 'transform';
  }

  let lastY = window.scrollY;
  let ticking = false;
  let isVisible = true;
  let isScrolled = false;
  let isAtTop = false;

  const setVisible = (v) => {
    if (v === isVisible) return;
    isVisible = v;
    navbar.style.transform = v ? 'translateY(0)' : `translateY(${hiddenY})`;
    if (!v) {
      document.querySelectorAll('.w-dropdown').forEach((d) => {
        d.querySelector('.w-dropdown-toggle')?.classList.remove('w--open');
        d.querySelector('.w-dropdown-list')?.classList.remove('w--open');
      });
    }
  };

  const setScrolled = (y) => {
    const s = y > 72;
    isScrolled = s;
    navbar.style.backgroundColor = s ? 'var(--_colours---neutral--neutral-100)' : '';

    const atTop = !s;
    if (atTop !== isAtTop) {
      isAtTop = atTop;
      navbar.classList.toggle('is-at-top', atTop);
    }
  };

  const update = () => {
    const y = window.scrollY;
    const scrollingDown = y > lastY;
    lastY = y;
    setScrolled(y);
    if (y <= 0 || y < 320 || document.querySelector('.w-dropdown-toggle.w--open, .w-dropdown-list.w--open')) {
      setVisible(true);
    } else {
      setVisible(!scrollingDown);
    }
  };

  update();

  window.addEventListener(
    'scroll',
    () => {
      if (!ticking) {
        ticking = true;
        requestAnimationFrame(() => {
          update();
          ticking = false;
        });
      }
    },
    { passive: true },
  );

  document.querySelectorAll('.w-dropdown').forEach((d) => {
    d.addEventListener('click', () => setTimeout(update, 0));
  });
});

// No scroll when mobile menu is open
const menuButton = document.querySelector('.navbar_menu-button');
menuButton.addEventListener('click', () => {
  menuButton.classList.toggle('w--open');
  document.body.classList.toggle('no-scroll');
});

// add 'page-loaded' class when DOM is ready
window.addEventListener("DOMContentLoaded", function () {
  document.documentElement.classList.add("page-loaded");
});

// handles sticky navbar show
document.addEventListener('DOMContentLoaded', () => {
  const stickyWrappers = document.querySelectorAll('[class*="sticky-active"]');
  const mediaQuery = window.matchMedia('(min-width: 992px)');

  // Detect the actual moving element
  const navbarWrapper =
        document.querySelector('.navbar_component')

  const checkNavbar = () => {
    if (!navbarWrapper) return;

    const transform = getComputedStyle(navbarWrapper).transform;
    if (!transform || transform === 'none') return;

    const matrix = transform.match(/^matrix.*\((.+)\)$/);
    if (!matrix) return;

    const values = matrix[1].split(', ');
    const translateY = parseFloat(values[5]);

    stickyWrappers.forEach(wrapper => {
      if (!mediaQuery.matches) {
        wrapper.classList.remove('is-navbar-shown');
      } else {
        if (translateY >= 0) {
          wrapper.classList.add('is-navbar-shown');
        } else {
          wrapper.classList.remove('is-navbar-shown');
        }
      }
    });
  };

  window.addEventListener('scroll', checkNavbar);
  window.addEventListener('resize', checkNavbar);
  checkNavbar();
});
